/* 바이라인 — src/ui/render.js
 * 일반 <script>로 index.html에 적힌 순서대로 실행된다. 순서를 바꾸지 말 것 (README의 로드 순서 참고).
 */


// ================= 렌더 =================
function render(){try{if(S&&S.phase==='game')ensureDeptEnts();}catch(e){}try{if(S&&S.phase==='game'&&!S.runInit){S.runInit=1;if(!S.dev&&!S.story&&S.turn<=8&&!window.__devTest)setTimeout(()=>{try{if($('#modal').hidden)runSetup();else Q.push(runSetup);}catch(e){}},700);}}catch(e){}
  syncDept();renderHud();renderTicker();try{bgmUpdate();}catch(e){}const app=$('#app');{const sk=S.phase+'|'+(S.phase==='game'?S.turn:'');if(window.__lastScr!==sk){if(window.__lastScr!==undefined)try{window.scrollTo({top:0,behavior:'instant'});}catch(e){window.scrollTo(0,0);}window.__lastScr=sk;}}
  try{fitAll();}catch(e){}
  if(S.phase==='title')app.innerHTML=titleHTML();
  else if(S.phase==='create')app.innerHTML=createHTML();
  else if(S.phase==='apply')app.innerHTML=applyHTML();
  else if(S.phase==='game')app.innerHTML=''+gameHTML();
  else if(S.phase==='end')app.innerHTML=endHTML();
  bind();drawScene();try{mobileNav();}catch(e){}
}
function renderTicker(){
  const el=$('#tickr');const items=(S&&S.ticker&&S.ticker.length)?S.ticker:[{t:'바이라인 — 수습기자의 첫 새벽부터 사장실까지'},{t:'통신사·방송·신문·온라인·잡지·전문지 51개 매체가 당신을 기다린다'}];
  const html=items.map(x=>`<span class="${x.me?'me':''}">${esc(x.t)}</span>`).join('');
  if(el.dataset.h!==html){el.innerHTML=html;el.dataset.h=html;}
}
function renderHud(){
  const h=$('#hud');if(S.phase!=='game'){h.innerHTML=(S.dev&&devOK()?'<button class="chip dv" data-go="devc">개발자 콘솔</button>':'')+(S.phase==='create'||S.phase==='apply'?'<button class="chip" data-go="title">처음으로</button>':'')+soundChip();bindHud();return;}
  const o=OUT();
  h.innerHTML=`<span class="chip ci">${ic('cal')}<span><b>${dateStr()}</b> · ${years()}년 차 · ${myAge()}세</span></span><span class="chip ci">${ic('bld')}<span>${esc(o.n)} · ${TYPES[o.type].n}</span></span><span class="chip ci">${ic('user')}<span>${deptName()} ${rankName()}</span></span><span class="chip ci hpc" style="--hp:${Math.round(S.hp)}%">${ic('heart')}<span>컨디션 <b>${Math.round(S.hp)}</b></span></span><span class="chip ci">${ic('coins')}<span>통장 ${moneyHud()}</span></span><span class="chip ci">${ic('gauge')}<span>${DF().n}</span></span>${S.dev&&devOK()?`<button class="chip dv" data-go="devc">개발자 콘솔</button>`:''}${soundChip()}<button class="chip ci" data-go="menu" style="border-color:var(--sodium)">${ic('menu')}<span>메뉴 · 새 게임</span></button>`;bindHud();
}
function titleHTML(){
  const nT=TPL.length+(typeof POS_TPL!=='undefined'?POS_TPL.length:0),nE=evCount();
  return `<section class="hero2">
   <div class="hcopy"><span class="kicker">기자 커리어 시뮬레이션 · v${VERSION}${parseFloat(VERSION)>=1?" 정식":""}</span>
    <h1>펜 하나로<br><em>편집국 꼭대기까지</em></h1>
    <p>새벽 경찰서를 도는 수습기자로 시작해 단독을 쫓고, 사실을 두 번 확인하고, 반론을 받아 기사를 낸다. 데스크가 되고, 편집국장이 되고, 사장실에 앉거나 — 아예 내 언론사를 세운다.</p>
    <div class="namecard" id="ncard"><label for="tnm">내 기자 이름 <small>· 한글·영어 2~8자</small></label><div class="nrow"><input id="tnm" maxlength="8" value="${esc(S.name||lastName())}" placeholder="예: 한서진" autocomplete="off" enterkeyhint="go"><button class="btn sm" data-go="rname" title="무작위 이름">랜덤</button></div><div class="bl" id="tbl">${nameLine(S.name||lastName())}</div></div>
    <div class="btns"><button class="btn pri" data-go="new">새 게임 시작</button>${hasSave()?'<button class="btn" data-go="cont">이어하기</button>':''}<button class="btn" data-go="load">불러오기</button><button class="btn" data-go="help">처음이라면? 도움말</button><button class="btn" data-go="quiz">상식 퀴즈 연습</button><button class="btn" data-go="hall">기록실${(META.runs||[]).length?` · ${META.runs.length}판`:''}</button></div>
    <div class="live" id="live">${liveHTML()}</div></div>
   <div class="stats4"><div><b>${OUTLETS.filter(o=>!o.custom).length}</b><span>언론사 (${new Set(OUTLETS.filter(o=>!o.custom).map(o=>o.type)).size}가지 매체 유형)</span></div><div><b>${nT.toLocaleString('ko-KR')}</b><span>기사 아이템 종류</span></div><div><b>${nE}+</b><span>이벤트</span></div><div><b>${QB.length}</b><span>언론고시 상식 문제</span></div><div class="howto"><div class="ht"><i>1</i><b>미션 확인</b><span>할 일 맨 위 이달의 미션</span></div><div class="ht"><i>2</i><b>취재 → 기사</b><span>사실을 확인하고 출고한다</span></div><div class="ht"><i>3</i><b>다음 달로</b><span>결산 보고, 승진을 향해</span></div></div></div>
  </section>
  <h2 class="sech">어떻게 시작할까</h2>
  <div class="modes">
   <button class="mode" data-go="new" data-pm="exam" style="--mc:#77a6ff"><span class="mi">시</span><b>언론고시 · 4곳 지망</b><span>원하는 매체 4곳에 지원해 서류·필기·면접을 본다. 대형 매체를 노린다면.</span></button>
   <button class="mode" data-go="new" data-pm="smb" style="--mc:#5ad49b"><span class="mi">입</span><b>중소·중견에서 바로</b><span>시험 없이 작은 매체에 입사. 일은 많지만 단독 기회도 빠르다.</span></button>
   <button class="mode" data-go="new" data-pm="story" style="--mc:#ff8fb1"><span class="mi">극</span><b>스토리 모드 · 5편</b><span>물먹은 수습, 지방지의 반란, X파일, 무너진 공영방송, 적자 매체 살리기.</span></button>
   <button class="mode" data-go="new" data-pm="simple" style="--mc:#9be36b"><span class="mi">쉽</span><b>간소화 모드</b><span>어려운 건 빼고 핵심만. 기사는 제목만 고르고, 승진은 두 배 빠르다. 짧게 즐기고 싶다면.</span></button>
   <button class="mode" data-go="new" data-pm="quick" style="--mc:#c59bff"><span class="mi">速</span><b>빠른 시작 · 경력 기자로</b><span>3년 차 기자·10년 차 부장·선거 앞둔 국장·갓 취임한 편집국장으로 바로. 수습 시절은 건너뛴다.</span></button>
   <button class="mode" data-go="new" data-pm="found" style="--mc:#ffb84d"><span class="mi">創</span><b>창간 모드 · 타이쿤</b><span>발행인으로 내 언론사를 세워 포털 CP·기자 80명·메이저까지 키운다.</span></button>
  </div>
  <h2 class="sech">이런 게임이에요</h2>
  <div class="feat">
   <div><b>진짜 같은 취재</b>전화·문건·현장·탐문·데이터·정보공개청구·인터뷰로 사실을 하나씩 확인한다. 핵심 사실은 두 출처로.</div>
   <div><b>기사 쓰기</b>야마·리드·팩트·반론·제목을 골라 출고. 단독·특종·대특종, 받아쓰기와 포털 메인.</div>
   <div><b>사람과 관계망</b>동료·취재원, 그리고 정부 기관·정당·인물·광고주. 처음엔 아는 곳이 거의 없다.</div>
   <div><b>데스크에서 사장까지</b>데스킹·광고 영업·편집회의·1면·인사권·포털 제휴·시설 투자·M&A급 결정.</div>
   <div><b>언론사 경쟁</b>경쟁 매체와 광고 파이를 나누고, 부수 공사·광고 덤핑·사설 전쟁이 벌어진다.</div>
   <div><b>3가지 난이도 · 목표</b>쉬움·보통·어려움. 커리어 목표와 업적, 여러 엔딩.</div>
  </div>
  <div class="btns" style="margin-top:6px"><button class="btn sm" data-go="tut">튜토리얼</button><button class="btn sm" data-go="patch">업데이트 내역</button>${devOK()?`<button class="btn sm" data-go="devtoggle">개발자 모드 ${S.dev?'끄기':'켜기'}</button>${S.dev?'<button class="btn sm" data-go="devc" style="border-color:var(--dev);color:var(--dev)">개발자 콘솔 · 빠른 시작</button>':''}`:''}</div>`;
}
function createHTML(){
  return `<div class="box"><div class="bh"><h3>지원자 프로필</h3><span class="num" style="color:var(--mute);font-size:12px">STEP 1/2</span></div><div class="bb">
  <div class="group"><div class="namecard" style="max-width:none;display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:0"><span style="color:var(--mute);font-size:13px">기자 이름</span><b style="font-size:20px;font-family:var(--f-display);font-weight:400">${esc(S.name)} 기자</b><button class="btn sm" data-go="title" style="margin-left:auto">메인에서 바꾸기</button></div></div>
  <div class="group qstart"><button class="next" data-go="quick" style="margin:0">바로 시작하기 — 수습기자로 입사 (추천)</button><p class="hint" style="margin:6px 2px 0">처음이라면 이걸로. 시험 없이 추천 매체 3곳 중 하나를 골라 바로 시작한다. 전공·스펙은 지금 고른 그대로(기본값) 들어간다.</p></div>
  <div class="group"><h4>시작 방식<small>언론고시 · 중소 매체 · 빠른 시작 · 창간</small></h4><div class="opts"><button class="opt" data-smode="exam" aria-pressed="${!S.smode||S.smode==='exam'}"><b>언론고시 · 4곳 지망</b><span>원하는 매체 4곳에 직접 지원해 서류·필기·면접을 본다. 대형 매체도 노릴 수 있다.</span></button><button class="opt" data-smode="smb" aria-pressed="${S.smode==='smb'}"><b>중소·중견 매체에서 시작</b><span>수시 채용으로 바로 입사한다. 작은 곳에서 경력을 쌓아 큰 매체로 이직하는 길.</span></button><button class="opt" data-smode="quick" aria-pressed="${S.smode==='quick'}"><b>빠른 시작 · 경력 기자로</b><span>3년 차 기자·10년 차 부장·선거를 앞둔 국장·갓 취임한 편집국장으로 바로 시작한다. 초반을 건너뛰는 대신 수습 시절 이야기·유산·도전 과제·초반 업적은 없다.</span></button><button class="opt" data-smode="story" aria-pressed="${S.smode==='story'}"><b>스토리 모드 · 5편</b><span>정해진 상황과 목표, 제한 시간이 있는 시나리오. 물먹은 수습부터 적자 매체 살리기까지.</span></button><button class="opt" data-smode="found" aria-pressed="${S.smode==='found'}"><b>창간 모드 · 타이쿤</b><span>10년 차 기자 출신 발행인으로 내 언론사를 세워 메이저로 키운다. 경영·편집·인사를 모두 쥔다.</span></button></div></div>
  <div class="group"><h4>플레이 방식<small>시작하면 2년(게임 시간)이 지나야 메뉴에서 바꿀 수 있다</small></h4><div class="opts"><button class="opt" data-simple="0" aria-pressed="${!S.simple}"><b>정통 모드</b><span>모든 기능과 콘텐츠. 사실 교차 확인, 기사 5단계, 관계망·동료·생활까지.</span></button><button class="opt" data-simple="1" aria-pressed="${!!S.simple}"><b>간소화 모드</b><span>핵심만 빠르게. 기사는 제목만 고르면 끝, 확인은 한 번씩, 승진은 두 배 빠르게, 이벤트·탭·행동은 꼭 필요한 것만.</span></button></div></div>
  <details class="more adv"><summary>자세히 설정 — 나이 · 난이도 · 전공 · 스펙</summary>
  ${ageGroupHTML()}
  <div class="group"><h4>난이도</h4><div class="opts">${Object.keys(DIFF).map(k=>`<button class="opt" data-diff="${k}" aria-pressed="${S.diff===k}"><b>${DIFF[k].n}</b><span>${DIFF[k].d}</span></button>`).join('')}</div></div>
  <div class="group"><h4>전공<small>배치 희망 시 적합 부서가 유리</small></h4><div class="opts">${MAJORS.map((m,i)=>`<button class="opt" data-major="${i}" aria-pressed="${S.major===i}"><b>${m.n}</b><span>${m.t}<br>${Object.entries(m.b).map(([k,v])=>`${STN[k]} ${v>0?'+':''}${v}`).join(' · ')}</span></button>`).join('')}</div></div>
  <div class="group"><h4>대표 스펙</h4><div class="opts">${SPECS.map((m,i)=>`<button class="opt" data-spec="${i}" aria-pressed="${S.spec===i}"><b>${m.n}</b><span>${m.t}<br>${Object.entries(m.b).map(([k,v])=>`${STN[k]} ${v>0?'+':''}${v}`).join(' · ')}</span></button>`).join('')}</div></div>
  <div class="group"><h4>능력치 미리보기<small>전공·스펙에 따라 장단점이 갈린다</small></h4>${statPreview()}</div></details>
  <button class="next" data-go="create">${S.smode==='story'?'다음: 스토리 고르기':S.smode==='found'?'다음: 창간 준비':S.smode==='smb'?'다음: 수시 채용':S.smode==='quick'?'다음: 경력 고르기':'다음: 언론고시 지원'}</button></div></div>`;
}
function applyHTML(){
  const sum=Object.values(S.st).reduce((a,b)=>a+b,0);const af=S.af||'전체';
  const gs=GROUPS.filter(([g])=>af==='전체'||g===af);
  return `<div class="box"><div class="bh"><h3>언론고시 · 지원할 매체 고르기 (최대 4곳)</h3><span class="num" style="color:var(--mute);font-size:12px">${S.retries?`${S.retries+1}수째 · `:''}STEP 2/2</span></div><div class="bb">
  <p class="hint" style="margin:0 0 10px">이번 시즌 공채 공고를 낸 곳은 전체 ${OUTLETS.filter(o=>!o.custom).length}곳 중 <b>${applyPool().length}곳</b>뿐이다(재수하면 공고가 바뀐다). 급(★)이 높을수록 경쟁률이 높다. 논조는 입사 후 기사 방향과 면접에 영향을 준다. 내 능력치 합 <b class="num">${Math.round(sum)}</b>. 지원 ${S.apply.length}/4${S.apply.length?' — '+S.apply.map(id=>OUTLETS.find(o=>o.id===id).n).join(', '):''}</p>
  <div class="btns" style="margin-bottom:14px">${['전체',...GROUPS.map(g=>g[0])].map(g=>`<button class="btn sm" data-af="${g}" style="${g===af?'border-color:var(--sodium);color:var(--sodium)':''}">${g} ${g==='전체'?applyPool().length:OUTLETS.filter(o=>TYPES[o.type].g===g&&applyPool().includes(o.id)).length}</button>`).join('')}</div>
  ${gs.map(([g,desc])=>{const os=OUTLETS.filter(o=>TYPES[o.type].g===g&&applyPool().includes(o.id)).sort((a,b)=>b.p-a.p);if(!os.length)return '';return `<div class="group"><h4>${g}<small>${desc}</small></h4><div class="opts">${os.map(o=>`<button class="oc" data-apply="${o.id}" aria-pressed="${S.apply.includes(o.id)}"><span class="on">${esc(o.n)}</span><span class="meta"><span class="tag bl">${TYPES[o.type].n}</span><span class="tag so">${LEAN[o.lean]}</span><span class="tag ok">${o.own}</span></span><span class="od">${o.d}</span><span class="meta">${otrTags(o)}${spmTag(o)}</span><span class="od" style="font-size:12px">회사 특성 — ${otrLine(o)}</span><span class="od">부서: ${o.depts.map(d=>DEPTS[d].n).join('·')}</span><span class="meta"><span class="stars">${'★'.repeat(o.p)}${'☆'.repeat(5-o.p)}</span><span>경쟁률 ${[0,0,40,90,180,320][o.p]}:1</span><span>초임 실수령 월 ${payOf(o,1)}만</span></span></button>`).join('')}</div></div>`;}).join('')}
  <button class="next" data-go="exam" ${S.apply.length?'':'disabled'}>지원서 제출 (${S.apply.length}곳)</button></div></div>`;
}
function bar(v,c){return `<div class="bar"><i style="width:${clamp(v,0,100)}%;--c:${c||'var(--sodium)'}"></i></div>`;}
// 6.8 할 일 버튼 결과 미리보기: 대략 무엇을 얻고 무엇을 쓰는지 (g 얻는 것 · r 드는 것)
