  const tg=TG.map(([g,n,l])=>[g,n,tabs.filter(t=>l.includes(t[0]))]).filter(x=>x[2].length);const curG=(tg.find(x=>x[2].some(t=>t[0]===S.tab))||tg[0]);S.tabLast=S.tabLast||{};S.tabLast[curG[0]]=S.tab;
