const ACT_GROUPS=[
 ['취재 현장','#77a6ff',['breaking','sasu','hari','beat','discover','invest','cfile','special','spx','spec','source','tour']],
 ['기사와 지면','#ffb84d',['rtact','gongse','write','fassign','assign','report','pitch','desk','meeting','front','column','direction','plan','taskforce','agenda','fethics','fcrisis']],
 ['사람과 관계','#ff8fb1',['deptlife','handoff','fhire','fbureau','colleague','drink','network','recruit','personnel','hire']],
 ['영업과 경영','#5ad49b',['exec','board','wage','adrate','revenue','lgevent','gad','fvision','fsales','fpartner','fbrand','fraise','adsell','adsales','campaign','digital','event','portal','facility','paypol','newdept','cut']],
 ['나의 생활','#b98cff',['life','rest','deptreq','job','found']]
];
function recommend(){const ok=id=>rankActs().includes(id)&&!why(id);
  if(S.breaking&&ok('breaking'))return 'breaking';
  if(S.hp<28&&ok('rest'))return 'rest';
  const due=S.items.find(i=>i.slot&&i.slot.due<=S.turn+0&&i.facts.some(fOK));if(due&&ok('write'))return 'write';
  const hot=S.items.find(i=>i.excl&&Math.ceil(i.heat/4)<=1);if(hot){if(hot.facts.filter(fOK).length>=2&&ok('write'))return 'write';if(ok('invest'))return 'invest';}
  if(S.rank===0){if(ok('sasu')&&S.items.length<3)return 'sasu';if(ok('invest')&&S.items.some(i=>i.facts.some(f=>!fOK(f))))return 'invest';if(ok('report'))return 'report';}
  if(bjDeskOn()&&ok('desk')){bjEnsure();if((S.dq||[]).length&&(((S.monthQ||[]).length>=2)||S.dq.some(d=>d.due-S.turn<=1)||S.dq.length>=3))return 'desk';}
  if(S.rank>=1&&S.rank<=3){if(ok('pitch'))return 'pitch';if(writable().some(i=>i.facts.filter(fOK).length>=3)&&ok('write'))return 'write';if(!S.items.length&&ok('discover'))return 'discover';if(ok('invest')&&S.items.length)return 'invest';}
  if(S.rank>=4&&S.rank<=6){for(const id of ['meeting','front','tour','taskforce'])if(ok(id))return id;}
  if(S.founder){if(S.co.cash<2){for(const id of ['fraise','fsales'])if(ok(id))return id;}if(!(S.fStrat&&S.fStrat.due>S.turn)&&ok('fvision'))return 'fvision';const o=OUT();if(S.co.staff<[0,0,12,30,55,80][o.p+1]&&S.co.cash>2&&ok('fhire'))return 'fhire';for(const id of ['portal','fsales','fbrand','meeting'])if(ok(id))return id;}
  if(S.rank===7){if(S.co.cash<3&&ok('cut'))return 'cut';if(ok('gad')&&!S.gadUsed)return 'gad';for(const id of ['portal','adsales','facility','campaign','digital'])if(ok(id))return id;}
  return null;}
function avaColor(){const h=[...(S.name||'기')].reduce((a,c)=>a+c.charCodeAt(0),0);const P=[['#5b7cff','#9a6bff'],['#ff8a5b','#ff5f8f'],['#2fc3a0','#3a8dff'],['#ffb84d','#ff7a45'],['#8d6bff','#ff6bc1']];return P[h%P.length];}
function dashHTML(needTxt){const o=OUT(),D=DF(),nr=RANKS[S.rank];const nx=nextRank(S.rank);const [c1,c2]=avaColor();
  let prog=0,reqs='',pl='';
  if(S.rank===0){const m=S.story?Math.round(RANKS[0].min*D.ten):rookieWeeks();prog=S.inRank/m;pl=`수습 ${moTxt(S.inRank)}/${moTxt(m)}`;reqs=S.story?`<span class="${S.eval>=38+DF().need/2?'ok':''}">평가 ${Math.round(38+DF().need/2)} 이상</span>`:rookieReqs().map(x=>`<span class="${x.ok?'ok':''}">${esc(x.t)}</span>`).join('');}
  else if(S.rank===7){const m=S.founder?0:ceoTermW();if(S.founder){const need=[0,0,55,70,85,100][o.p+1]||100;prog=Math.min(1,(S.fScore||0)/need);pl=`매체 위상 ★${o.p} → ★${Math.min(5,o.p+1)}`;reqs=`<span class="${(S.fScore||0)>=need?'ok':''}">성장 점수 ${Math.round(S.fScore||0)}/${need}</span><span class="${S.co.staff>=[0,0,12,30,55,80][o.p+1]?'ok':''}">기자 ${S.co.staff}/${[0,0,12,30,55,80][o.p+1]||'-'}명</span><span class="${S.portal&&S.portal.lv===3?'ok':''}">포털 ${S.portal?PORTAL[S.portal.lv]:'-'}</span>`;}else{prog=S.inRank/m;pl=`사장 임기 ${moTxt(S.inRank)}/${moTxt(m)}`;}}
  else if(nx!=null){const m=promoMinW(S.rank);const pr=[Math.min(1,S.inRank/m),Math.min(1,Math.max(0,S.eval)/promoEv(S.rank)),Math.min(1,Math.max(0,S.fame)/promoFm(S.rank))];try{const L=promoReqs(S.rank);if(L.length)pr.push(L.filter(x=>x.ok).length/L.length);}catch(e){}prog=Math.min(1,pr.reduce((a,b)=>a+b,0)/pr.length);pl=`다음 직급 <b>${rankName(nx)}</b>`;reqs=`<span class="${S.inRank>=m?'ok':''}">재직 ${moTxt(S.inRank)}/${moTxt(m)}</span><span class="${S.eval>=promoEv(S.rank)?'ok':''}">평가 ${promoEv(S.rank)}</span><span class="${S.fame>=promoFm(S.rank)?'ok':''}">평판 ${promoFm(S.rank)}</span>${promoReqHTML(S.rank)}<span>정기 인사까지 ${moTxt(24-S.turn%24)}</span>`;}
  else{prog=1;pl='최고 직급';}
  const ring=(v,c,n)=>{const k={'업계 평판':'fame','신뢰도':'trust','컨디션':'hp'}[n]||'eval';return `<div data-ev="${k}" title="${esc(evTip(k))}" style="cursor:pointer"><div class="ring" style="--v:${Math.round(clamp(v,0,100))};--c:${c}"><b>${Math.round(v)}</b></div><small>${n}</small></div>`;};
  const rec=recommendStat();const jj=Math.round(judgment());const tip=rec?`<div class="nudge"><b>지금 할 만한 일</b>${actName(rec)} — ${ACT[rec].d}<br><span style="opacity:.7;font-size:11.5px">${S.simple?'간소화 모드 추천':`${S.founder?'비전':'판단력'} ${jj} — 높을수록 추천이 자주, 정확하게 뜬다`}</span></div>`:`<div class="nudge" style="opacity:.65"><b>감이 오지 않는다</b>이번 달은 스스로 판단하자 (${S.founder?'비전':'판단력'} ${jj})</div>`;
  const goal=S.story?(()=>{const st=storyDef();return st?`<div class="nudge" style="background:rgba(119,166,255,.08);border-color:rgba(119,166,255,.3);color:#cfe0ff"><b style="color:var(--siren)">스토리</b>${esc(st.txt())}</div>`:'';})():'';
  return `<section class="dash" aria-label="상황판">
   <div class="dcard"><div class="who"><div class="ava hasb" style="--c1:${c1};--c2:${c2}" title="${esc(rankName())}">${rankBadge(S.rank)}<i>${esc((S.name||'?')[0])}</i></div><div style="min-width:0"><h2>${esc(S.name)} ${rankName()}</h2><p>${esc(o.n)} · ${TYPES[o.type].n} · ${deptName()}</p><p>${dateStr()} · ${years()}년 차${S.atOutlet!=null&&Math.floor(S.atOutlet/YW)+1<years()?` (이 회사 ${Math.floor(S.atOutlet/YW)+1}년 차)`:''} · ${ageLine()} · ${DF().n}</p></div></div>
    <div class="prog"><div class="pl"><span>${pl}</span><span class="num">${Math.round(prog*100)}%</span></div>${bar(prog*100,'var(--sodium)')}<div class="reqs">${reqs}</div>${rookieSkipOK()?`<button class="btn sm" data-skiprk style="margin-top:8px">⏩ 수습 건너뛰기</button>`:''}</div></div>
   <div class="dcard"><div class="rings">${ring(S.eval,'var(--siren)',S.founder?(S.investor?'투자자 신뢰':'구성원 신뢰'):S.rank===7?'이사회':'사내 평가')}${ring(S.fame,'var(--sodium)','업계 평판')}${ring(S.trust,'var(--good)','신뢰도')}${ring(S.hp,S.hp<30?'var(--red)':'var(--pink)','컨디션')}</div>${tip}</div>
   <div class="dcard"><div class="mini"><div><span>행동력</span><b>${S.ap}</b></div><div><span>통장</span><b>${S.money.toLocaleString('ko-KR')}만</b></div><div><span>내 월급 (실수령)</span><b style="color:var(--good)">${payOf(OUT()).toLocaleString('ko-KR')}만</b></div><div><span>한 달 생활비</span><b>${living().toLocaleString('ko-KR')}만</b></div><div><span>${S.rank>=5?'회사 자금':'단독 · 기사'}</span><b>${S.rank>=5?f1(S.co.cash)+'억':`${S.scoops} · ${S.totalArticles||0}`}</b></div><div><span>취재 중 아이템</span><b>${S.items.length}건</b></div></div>${goal}</div>
  </section>`;}
function tabBody(){
  const t=S.tab,o=OUT();
  if(t==='road'){const h=`${endGoalBox()}${S.story?storyBox():goalsBox()}${styleHTML()}${valBox()}${v12Road()}${threadsHTML()}${milesHTML()}${slHTML()}`;return h||'<p class="empty">아직 쌓인 이야기가 없다.</p>';}
  if(t==='world'){const h=`${spmBox()}${v12World()}${eraBox()}${figBox()}${relGlance()}`;return h||'<p class="empty">아직 보이는 흐름이 없다.</p>';}
  if(t==='me'){const rv=S.rival;return `${ftBox()}${promoLineHTML()}${rankBox()}${corrBox()}${S.founder?`${fMixBox()}<p class="hint" style="margin:10px 0 0">발행인은 기자와 다른 능력치로 회사를 이끈다. 행동마다 관련 능력치가 오른다.</p>${fstBox()}<div class="sec">기자 시절 능력치</div><p class="hint" style="margin:0">${Object.keys(STN).map(k=>`${STN[k]} ${Math.round(S.st[k])}`).join(' · ')}</p>`:`<div class="sec">능력치 <b style="margin-left:6px;color:var(--sodium)">종합 실력 ${mySkill()}</b> <small style="font-weight:400;color:var(--mute)">누르면 설명</small></div>${skillCmpHTML()}<div class="stg">${STG.map(([g,ks],gi)=>ks.map(k=>`<button type="button" class="stt" data-stat="${k}" title="${esc(statTitle(k))}" style="--gc:${['#77a6ff','#ffb84d','#ff8fb1','#5ad49b','#b98cff'][gi]}"><span>${STN[k]}</span><b>${Math.round(S.st[k])}</b><i style="width:${clamp(S.st[k],0,100)}%"></i></button>`).join('')).join('')}</div><div class="stl">${STG.map(([g],gi)=>`<span style="--gc:${['#77a6ff','#ffb84d','#ff8fb1','#5ad49b','#b98cff'][gi]}">${g}</span>`).join('')}</div>`}
   <div class="sec">평가</div><div class="stg stg4">
   <button type="button" class="stt" data-ev="eval" title="${esc(evTip('eval'))}" style="--gc:var(--siren)"><span>${S.founder?(S.investor?'투자자 신뢰':'구성원 신뢰'):S.rank===7?'이사회':'사내평가'}</span><b>${Math.round(S.eval)}</b><i style="width:${clamp(S.eval,0,100)}%"></i></button>
   <button type="button" class="stt" data-ev="fame" title="${esc(evTip('fame'))}" style="--gc:var(--sodium)"><span>업계평판</span><b>${Math.round(S.fame)}</b><i style="width:${clamp(S.fame,0,100)}%"></i></button>
   <button type="button" class="stt" data-ev="trust" title="${esc(evTip('trust'))}" style="--gc:var(--good)"><span>신뢰도</span><b>${Math.round(S.trust)}</b><i style="width:${clamp(S.trust,0,100)}%"></i></button>
   <button type="button" class="stt" data-ev="hp" title="${esc(evTip('hp'))}" style="--gc:${S.hp<30?'var(--red)':'var(--mute)'}"><span>컨디션</span><b>${Math.round(S.hp)}</b><i style="width:${clamp(S.hp,0,100)}%"></i></button></div>
   ${rv?`<div class="sec">${rv.pub?'경쟁 매체':'라이벌'}</div><div class="card"><div class="t">${esc(rv.name)}${rv.pub?' 대표':''} <span style="font-weight:400;color:var(--mute)">· ${OUTLETS.find(x=>x.id===rv.outlet).n}</span></div><div class="meta">${rv.pub?`<span>우리 아이템 선점 ${rv.wins}회</span><span>우리 기자 빼감 ${rv.poach||0}명</span>`:`<span>실력 ${Math.round(rv.skill)}</span><span>나를 물먹인 횟수 ${rv.wins}</span>`}</div></div>`:''}
   <div class="sec">경력</div><div class="kv"><div><span>출고 기사</span><b>${S.totalArticles||0}</b></div><div><span>단독</span><b>${S.scoops}</b></div><div><span>수상</span><b>${S.awards}</b></div><div><span>오보</span><b>${S.errors}</b></div><div><span>거친 매체</span><b>${new Set(S.history).size}</b></div></div>
   <p class="hint">${S.history.map(id=>OUTLETS.find(x=>x.id===id).n).join(' → ')}</p>
   <div class="sec">업적 ${Object.keys(S.ach).length}/${Object.keys(ACH).length}</div>${Object.keys(S.ach).length?`<div class="achs">${Object.keys(ACH).filter(k=>S.ach[k]).map(k=>`<div class="on">${ACH[k][0]}<small>${S.ach[k]}</small></div>`).join('')}</div>`:''}<details class="fold"><summary>아직 못 딴 업적 ${Object.keys(ACH).filter(k=>!S.ach[k]).length}개 보기</summary><div class="achs">${Object.keys(ACH).filter(k=>!S.ach[k]).map(k=>`<div>${ACH[k][0]}<small>${ACH[k][1]}</small></div>`).join('')}</div></details>`;}
  if(t==='items'){if(!S.items.length)return `<p class="empty">아이템이 없다. ${S.rank===0?`${sasuN()}부터 해 보자.`:'발굴하거나 브리핑에 가거나 취재원을 만나자.'}</p>`;
    return S.items.map(it=>`<div class="card"><div class="t">${gradeTag(it)} ${esc(it.title)}${it.hoaxHint?' <span class="tg new">수상한 제보</span>':''}${it.chain?` <span class="tg h">후속 ${it.chain}</span>`:''}</div><div class="meta"><span class="tag bl ctag">${catImg(it.d)}${DEPTS[it.d].n}</span>${it.exclLost&&!it.excl?'<span class="tag">타사도 안다</span>':''}${it.excl?`<span class="tag ex">단독 · 추격까지 ${heatTxt(it.heat)}</span>`:`<span class="tag">공통 · ${it.slot?'발제 배정':`철 지나기까지 ${heatTxt(it.heat+1)}`}</span>`}${it.slot?`<span class="tag so">${SLOT[it.slot.g].n} · 마감 ${heatTxt(it.slot.due-S.turn+1)}</span>`:''}<span>파급력 ${it.imp}</span>${timTag44(it)}<span>${it.pos?'코멘트':'반론'} ${it.rebut==='got'?'받음':it.rebut==='no'?'노코멘트':'없음'}</span><span>경계 ${Math.round(it.alert)}</span>${it.src?`<span>출처 ${esc(it.src)}</span>`:''}${it.jt?`<span class="tag ok">공동 취재 · ${esc(it.jt.who)}</span>`:it.race&&it.race.d&&!it.race.done?`<span class="tag ex">${jo2(esc(DEPTS[it.race.d].n),'과','와')} 경쟁 중</span>`:''}</div>${itEntHTML(it)}${factList(it)}${it.slot||it.story?'':`<button class="btn sm ghostb" data-dropit="${it.id}" style="margin-top:6px">이 아이템 접기</button>`}</div>`).join('');}
  if(t==='src'){S.newSrc=0;if(!S.sources.length)return '<p class="empty">아직 취재원이 없다.</p>';return `<p class="hint" style="margin:0 0 8px">취재원 ${S.sources.length}명 · 인원 제한 없음. 오래 안 만나도 사라지지 않지만, 배신하거나 신원이 노출되면 떠날 수 있다.</p>`+(S.sources.length>4?sortChips(SRC_SORT,SRC_SORT[S.srcSort]?S.srcSort:'rec','data-tss'):'')+srcSorted(S.sources,SRC_SORT[S.srcSort]?S.srcSort:'rec').map(s=>`<div class="card srcc">${face(srcFaceRole(s),(s.trust||0)-10,'sf',s.name)}<div class="t">${(s.fresh??-99)>=S.turn-4?'<span class="tg new">NEW</span>':''}${esc(s.name)} <span style="font-weight:400;color:var(--mute)">· ${esc(s.role)}</span>${s.fig?' <span class="tag so">평생 인연</span>':''}</div><div class="meta"><span class="tag bl">${DEPTS[s.d].n}</span><span>${PERS[s.pers].n}</span><span>신뢰 ${Math.round(s.trust)}${s.trust>=40?' · 문건 가능':''}</span></div>${bar(s.trust,'var(--good)')}</div>`).join('');}
  if(t==='clips'){if(!S.clips.length)return '<p class="empty">아직 출고한 기사가 없다.</p>';return S.clips.map(c=>clipHTML(c,1)+`<p class="meta" style="margin:-4px 0 12px">완성도 ${c.q} · 파급력 ${c.imp} · 조회 ${c.views.toLocaleString('ko-KR')}${c.portal&&c.portal<=50?` · 포털 ${c.portal}위`:''}${c.awarded?' · 기자상':''}${c.after?` · 그 후: ${esc(c.after)}`:''}</p>`).join('');}
  if(t==='co'){const c=S.co,l=c.last;return `<div class="sec">${esc(o.n)} · ${TYPES[o.type].n} · ${LEAN[o.lean]} · ${o.own}</div><p class="hint" style="margin:0 0 8px">사장 <b>${esc(leaders().ceo)}</b> · ${isTV()?'보도국장':'편집국장'} <b>${esc(leaders().chief)}</b><br>직급 체계: ${rankChain().map(r=>rankName(r)).join(' → ')} · 부서 ${o.depts.length}개(${o.depts.map(d=>DEPTS[d].n).join('·')})</p>
   <div class="kv"><div><span>${TYPES[o.type].sub}</span><b>${f1(c.subs)}${TYPES[o.type].unit}</b></div><div><span>일 방문자</span><b>${f1(c.tr)}만</b></div><div><span>편집국 인원</span><b>${c.staff}명</b></div><div><span>보도 품질</span><b>${Math.round(c.q)}</b></div><div><span>회사 자금</span><b>${eok(c.cash)}</b></div><div><span>월 손익</span><b style="color:${!l||l.profit>=0?'var(--good)':'var(--red)'}">${l?(l.profit>=0?'+':'')+eok(l.profit):'—'}</b></div></div>
   ${l?`<p class="hint">${l.mo?`${l.mo}월 · 광고 ${l.seaA>=1.05?'성수기':l.seaA<=.92?'비수기':'평월'}${l.mo===12?' · 연말 성과급':l.mo===1?' · 연봉 조정':''} · `:''}${l.one?`${esc(l.one.t)} (${l.one.v>0?'+':''}${eok(l.one.v)}) · `:''}매출 ${eok(l.rev)} (광고 ${eok(l.ad)}${l.netLoss>=.0005?` · 광고 중단·축소 -${eok(l.netLoss)}`:''}${l.netGain>=.0005?` · 관계 덕 광고 확대 +${eok(l.netGain)}`:''}) · 비용 ${eok(l.cost)}</p>`:''}
   ${S.rank>=2&&S.rank<=6?`<div class="sec">광고·협찬 영업</div><div class="kv"><div><span>${deptShared()?'부서 반기 실적 (공동)':'이번 반기 실적'}</span><b>${eok(myQ())}</b></div>${quota()?`<div><span>분기 목표${S.rank<=3?` (${DEPTS[S.dept]?DEPTS[S.dept].n:''} 광고 배정 ${deptAd(S.dept)>=1.3?'많음':deptAd(S.dept)<=.5?'적음':'보통'})`:''}</span><b>${eok(quota())}</b></div>`:''}<div><span>누적 실적</span><b>${eok(S.adTotal||0)}</b></div></div>`:''}${deptAdBox()}${standBox()}<div class="sec">포털 제휴</div><div class="kv"><div><span>등급</span><b style="font-size:14px">${S.portal?PORTAL[S.portal.lv]:'-'}</b></div><div><span>벌점</span><b>${S.portal?S.portal.pen:0}</b></div><div><span>트래픽 배율</span><b>×${f1(portalMult())}</b></div>${l&&l.cp?`<div><span>CP 전재료</span><b>${eok(l.cp)}</b></div>`:''}</div>${S.rank>=5||S.founder?revBox()+lgeBox():''}${opBox()}${finBox()}${ownBox()}${circBox()}${otrBox()}${S.comp?`<div class="sec">광고 시장 경쟁</div>${[{n:o.n,s:S.myShare||0,me:1}].concat(S.comp.map(x=>({n:OUTLETS.find(y=>y.id===x.id).n,s:x.share||0}))).sort((a,b)=>b.s-a.s).map(x=>`<div class="statrow" style="grid-template-columns:120px minmax(0,1fr) 44px"><span style="${x.me?'color:var(--sodium);font-weight:700':''}">${esc(x.n)}</span>${bar(x.s*2.2,x.me?'var(--sodium)':'var(--siren)')}<span class="num">${f1(x.s)}%</span></div>`).join('')}${compBox()}`:''}${Object.keys(S.facil||{}).length?`<div class="sec">시설</div><p class="hint">${Object.keys(S.facil).map(k=>FACIL[k][0]).join(' · ')}</p>`:''}${S.founder?`<div class="sec">창간 성장</div><p class="hint">매체 위상 ★${o.p} · 성장 점수 ${Math.round(S.fScore||0)} · 기자 ${c.staff}명 · 목표: ★5·CP·기자 80명</p>`:''}<div class="sec">회사 자금 추이</div>${spark(c.hist)}<p class="hint">${S.rank<5?'경영 결정은 국장부터 관여한다. 내 기사 품질이 회사 품질에 반영된다.':'구독·광고·투자 결정이 매달 결산에 반영된다.'}</p>`;}
  if(t==='net')return netTabHTML();
  if(t==='adv')return advTabHTML();
  if(t==='cols'){if(!S.cols||!S.cols.length)return '<p class="empty">아직 동료가 없다.</p>';const CC=corrs();const corrBox=!CC.length&&!S.founder&&corrPlan(OUT()).alt?`<div class="sec">지역 취재</div><p class="hint" style="margin:0 0 6px">우리 회사엔 지역 주재기자가 없다. 지역 기사는 ${jo2(corrAlt(),'으로','로')} 메운다.</p>`:CC.length&&!['nat','loc','sigun'].includes(S.dept)?`<div class="sec">지역 주재기자 연락망 ${CC.length}명</div><p class="hint" style="margin:0 0 6px">다른 지역 기사를 쓸 땐 이들에게 먼저 전화한다. 관계가 좋으면 같이 써 주고 제보도 넘겨 준다.</p>${[...new Set(CC.map(m=>m.reg))].map(r=>`<p class="meta" style="margin:2px 0"><b style="color:var(--fg)">${esc(r)}</b> ${CC.filter(m=>m.reg===r).map(m=>`${esc(m.name)}(${yrsTxt(m)} · ${npcAge(m)}세·관계 ${Math.round(m.rel||0)})`).join(', ')}</p>`).join('')}`:'';return colsTabHTML(corrBox+(S.team.length?`<p class="hint">이 밖에 ${S.rank>=4?'편집국':'부서'}원 ${S.team.length}명 — '부서원' 탭</p>`:''));}
  if(t==='team')fixTeam();
  if(t==='team'&&S.rank>=6){const per=roster();const MRn=MR;return `<p class="hint" style="margin:0 0 10px">편집국 전체 ${S.co.staff}명을 부서별로 본다. 부서를 누르면 명단이 펼쳐진다. 실력은 겉으로 본 추정치.</p>`+Object.keys(per).filter(d=>dn(d)&&per[d].length).map(d=>{const L=per[d].slice().sort((a,b)=>(b.r||0)-(a.r||0)||b.skill-a.skill);const av=Math.round(L.reduce((a,m)=>a+m.skill,0)/L.length);const head=L.find(m=>(m.r||0)>=2)||L.find(m=>m.acting)||L[0];return `<details class="card"><summary style="cursor:pointer"><b>${dn(d)}</b> <span class="meta" style="display:inline-flex"><span>${L.length}명</span><span>평균 실력 ${av}</span><span>${head.acting?'부장 직무대리':['기자','차장','부장','부국장'][Math.min(3,head.r||0)]} ${esc(head.name)}</span>${L.some(m=>S.team.includes(m))?'<span class="tag so">직속</span>':''}</span></summary>${bar(av,'var(--siren)')}<ul class="loglist" style="margin-top:8px">${L.map(m=>`<li><span>${m.reg?'주재':rTitle(m)}</span>${esc(m.name)}${m.reg?` · ${esc(m.reg)}`:''} · ${yrsTxt(m)} · ${npcAge(m)}세 · ${payTxt(m)} · 실력 ${estRange(m.skill,30,m.name.length*7,'sk')}</li>`).join('')}</ul></details>`;}).join('');}
  if(t==='team')return deptBox()+(S.team.length?S.team.slice().sort((a,b)=>(b.r||0)-(a.r||0)||b.skill-a.skill).map(m=>`<div class="card mcard">${npcFace(m)}<div class="t">${esc(m.name)} ${rTitle(m)} <span style="font-weight:400;color:var(--mute)">· ${yrsTxt(m)} · ${npcAge(m)}세 · ${payTxt(m)}</span></div><div class="meta"><span class="tag bl">${DEPTS[m.d]?DEPTS[m.d].n:''}</span><span>종합 실력 ${Math.round(m.skill)}</span>${m.ai?`<span>${npcLine(m)}</span>`:''}${m.st?`<span>추정 ${['inv','wri','ver','net'].map(k=>`${STN[k]} ${estRange(m.st[k],S.rank>=2?40:10,m.name.length*7,k)}`).join(' · ')}</span>`:''}</div>${bar(m.skill,'var(--siren)')}</div>`).join(''):'<p class="empty">부서원이 없다.</p>');
  if(t==='mates'&&['nat','loc','sigun'].includes(S.dept)&&corrs().length){const C=corrs();const regs=[...new Set(C.map(m=>m.reg))];const M0=deptMates();const M=(M0.filter(m=>m.hq).length?M0.filter(m=>m.hq):M0).slice(0,3);return `<p class="hint" style="margin:0 0 10px">${jo2(DEPTS[S.dept].n,'은','는')} 본사 데스크 몇 명과 지역마다 1~3명씩 흩어진 주재기자로 이뤄진다. 나는 <b>${esc(S.region||'')}</b>. 전체 ${C.length+M.length}명.</p><div class="sec">본사 데스크</div>`+M.map(m=>`<div class="card mcard">${npcFace(m)}<div class="t">${esc(m.name)} <span style="font-weight:400;color:var(--mute)">· ${m.role} · ${yrsTxt(m)} · ${npcAge(m)}세 · ${payTxt(m)}</span></div></div>`).join('')+regs.map(r=>`<div class="sec">${esc(r)}${regMine43(r)?' · 내 담당 지역':''}</div>`+C.filter(m=>m.reg===r).map(m=>`<div class="card"><div class="t">${esc(m.name)} <span style="font-weight:400;color:var(--mute)">· ${m.role} · ${yrsTxt(m)} · ${npcAge(m)}세 · ${payTxt(m)}</span></div><div class="meta"><span>추정 ${['inv','net'].map(k=>`${STN[k]} ${estRange(m.st[k],(m.rel||0)+20,m.name.length*7,k)}`).join(' · ')}</span><span>관계 ${Math.round(m.rel||0)}</span></div></div>`).join('')).join('');}
  if(t==='mates'){const M=deptMates();return deptBox()+`<p class="hint" style="margin:0 0 10px">${esc(OUT().n)} ${DEPTS[S.dept].n} 사람들. 능력치는 겉으로 본 추정치라 범위로 보인다 — 오래 같이 일할수록 좁아진다.</p>`+M.map(m=>`<div class="card mcard">${npcFace(m)}<div class="t">${esc(m.name)} <span style="font-weight:400;color:var(--mute)">· ${m.role} · ${yrsTxt(m)} · ${npcAge(m)}세 · ${payTxt(m)}</span></div><div class="meta"><span>추정 ${['inv','wri','ver','net'].map(k=>`${STN[k]} ${estRange(m.st[k],(m.rel||0)+Math.min(40,S.inRank),m.name.length*7,k)}`).join(' · ')}</span></div>${bar(clamp(m.skill+((m.name.length*13)%15-7),5,99),'var(--siren)')}</div>`).join('');}
  if(t==='org'){const L=leaders(),rows=orgCounts();const per=roster();const tot=rows.reduce((a,r)=>a+r[1],0);
    return `<div class="kv"><div><span>사장(대표)</span><b style="font-size:15px">${esc(L.ceo)}</b></div><div><span>${isTV()?'보도국장':'편집국장'}</span><b style="font-size:15px">${esc(L.chief)}</b></div><div><span>기자</span><b>${tot}명</b></div><div><span>전체 임직원</span><b>${employees()}명</b></div></div><p class="hint" style="margin:6px 0 0">임직원에는 총무·광고·판매·제작·기술 인력이 포함된다. 아래는 편집국(보도국) 기자만 센 것이다.</p>
    <div class="sec">직급별 인원</div>${rows.map(([n,c,who])=>`<div class="statrow" style="grid-template-columns:96px minmax(0,1fr) 48px"><span>${n}</span>${bar(Math.min(100,c/Math.max(1,tot)*250),'var(--siren)')}<span class="num">${c}</span></div>${who?`<p class="hint" style="margin:-4px 0 6px 104px;font-size:11.5px">${esc(who)}</p>`:''}`).join('')}
    <div class="sec">부서장</div>${Object.keys(per).filter(d=>dn(d)&&per[d].length).map(d=>{const isReg=isRegD(d);const me=!S.founder&&S.rank===3&&d===S.dept;return `<p class="meta" style="margin:3px 0"><b style="color:var(--fg)">${dn(d)}</b> ${per[d].length+(me?1:0)}명 · ${isReg?`지역 ${new Set(per[d].map(m=>m.reg).filter(Boolean)).size}곳`:headLabel(per,d)}</p>`;}).join('')}
    <p class="hint">사장과 편집국장은 회사에 단 한 명. 일반 부서의 부서장은 부서마다 한 명이다. 작은 부서는 차장이 부장 직무대리를 맡기도 하고, 큰 부서엔 차장이 둘 이상일 수 있다.</p>`;}
  if(t==='log')return logTabHTML();
  return '';
}
function goalsBox(){S.goals=S.goals||{};const G=myGoals();return `<div class="sec">이번 판의 목표 ${G.filter(g=>S.goals[g.id]).length}/${G.length}</div><p class="hint" style="margin:-2px 0 8px">${S.founder?`창간 모드 전용 ${FOUNDER_GOALS.length}가지 중 3가지가 정해진다. 2가지를 이루면 창간 엔딩을 볼 수 있고, 셋 다 이루면 완전 클리어.`:`판마다 ${GOAL_POOL.length}가지 중 3가지가 정해진다. 셋 다 이루면 완전 클리어.`}</p>${G.map(g=>`<div class="card" style="${S.goals[g.id]?'border-color:var(--sodium)':''}"><div class="t">${S.goals[g.id]?'달성 · ':''}${g.n}</div><div class="meta"><span>${g.d}</span><span>${S.goals[g.id]?S.goals[g.id]:g.p()}</span></div></div>`).join('')}`;}
function spark(h){if(h.length<2)return '<p class="empty">한 달이 지나면 추이가 그려진다.</p>';const W=300,H=70,mn=Math.min(...h,0),mx=Math.max(...h,1),sx=i=>i/(h.length-1)*(W-8)+4,sy=v=>H-6-(v-mn)/(mx-mn||1)*(H-14);
  const pts=h.map((v,i)=>`${sx(i).toFixed(1)},${sy(v).toFixed(1)}`).join(' ');const z=sy(0);
  return `<svg class="spark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="회사 자금 추이"><line x1="0" x2="${W}" y1="${z}" y2="${z}" stroke="var(--line)" stroke-dasharray="3 3"/><polygon points="4,${z} ${pts} ${sx(h.length-1)},${z}" fill="var(--sodium)" opacity=".15"/><polyline points="${pts}" fill="none" stroke="var(--sodium)" stroke-width="2"/><rect x="${sx(h.length-1)-3}" y="${sy(h[h.length-1])-3}" width="6" height="6" fill="var(--sodium)"/></svg>`;}
function endImgKey(k){k=String(k||'');return /실패|파산|해임|해고|퇴사|중단|개발자|몰락|연루|퇴출|꺾이|유포자|적발/.test(k)?'end_fired':/창간|매각/.test(k)&&!/은퇴|승계|10주년/.test(k)?'end_found':'end_retire';}
function endHTML(){
  const best=S.clips.slice().sort((a,b)=>b.imp-a.imp)[0];
  const score=S.rank*14+S.fame*.6+S.trust*.4+S.scoops*2+S.awards*6-S.errors*4+(DF()===DIFF.hard?15:DF()===DIFF.easy?-10:0);
  const grade=score>=150?'전설의 언론인':score>=110?'존경받는 언론인':score>=75?'믿음직한 베테랑':score>=45?'성실한 기자':'짧았던 기자 생활';
  return `<div class="box"><div class="bh"><h3>${esc(S.endKind)} · 커리어 결산</h3><span class="num" style="color:var(--mute);font-size:12px">${dateStr()} · ${DF().n}${S.devUsed?' · 개발자 모드 사용':''}</span></div><div class="bb">
  <section class="hero endhero">${imgTag(endImgKey(S.endKind),'endimg')}<div><h1 style="font-size:clamp(34px,6vw,54px)">${grade}</h1><p>${S.styT&&STYLE[S.styT]?`업계는 ${jo2(esc(S.name),'을','를')} <b style="color:${STYLE[S.styT].c}">「${esc(STYLE[S.styT].n)}」</b>로 기억한다. `:''}${esc(valEndLine())}${esc(S.name)}, 최종 직급 ${rankName()} · ${esc(OUT().n)}. ${years()}년 차, ${myAge()}세에 마친 기자 생활.</p></div></section>
  ${giftCard()}<div class="kv" style="margin:12px 0"><div><span>출고 기사</span><b>${S.totalArticles||0}</b></div><div><span>단독</span><b>${S.scoops}</b></div><div><span>수상</span><b>${S.awards}</b></div><div><span>오보</span><b>${S.errors}</b></div><div><span>업계 평판</span><b>${Math.round(S.fame)}</b></div><div><span>신뢰도</span><b>${Math.round(S.trust)}</b></div><div><span>업적</span><b>${Object.keys(S.ach).length}</b></div></div>
  ${best?`<div class="sec">대표 기사</div>${clipHTML(best)}`:''}
  <div class="sec">걸어온 길</div><p class="hint">${S.history.map(id=>(OUTLETS.find(x=>x.id===id)||{n:id}).n).join(' → ')}</p>${nextRunHTML()}
  <div class="btns" style="margin-top:14px"><button class="btn pri" data-go="new">새 커리어 시작</button>${!S.story&&!S.dev?`<button class="btn" data-go="new" onclick="heirSave()" title="믿을 만한 취재원과 이름값, 원한을 후배가 물려받는다">후배로 이어 하기</button>`:''}<button class="btn" data-go="title">타이틀로</button></div></div></div>`;
}
function bind(){
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{const g=b.dataset.go;
    if(g==='new'){if(!startCreate())return;const pm=b.dataset.pm;if(pm==='simple'){S.simple=true;S.smode='smb';render();}else if(pm){S.smode=pm;render();}}else if(g==='cont'){const dv=S.dev;S=migrate(loadGame());S.dev=S.dev||dv;flashLoad('편집국으로 돌아가는 중…',700);render();}
    else if(g==='create')finishCreate();else if(g==='quick')quickStart();else if(g==='exam'){if(S.apply.length)startExam();}
    else if(g==='week')tryEndMonth();
    else if(g==='title'){const dv=S.dev;S=newState();S.dev=dv;render();}
    else if(g==='menu')gameMenu();
    else if(g==='sound')soundMenu();
    else if(g==='rname'){const el=$('#tnm');if(el){el.value=rname();el.dispatchEvent(new Event('input'));}}
    else if(g==='quiz')practiceStart();
    else if(g==='tut')tutorial(0);
    else if(g==='patch')patchNotes();else if(g==='help')helpCenter('start');else if(g==='hall')hallOpen();else if(g==='load')saveMenu();else if(g==='devc'){devConsole();}else if(g==='devtoggle'){if(!devOK())return;S.dev=!S.dev;try{localStorage.setItem('byline-dev',S.dev?'1':'0');}catch(e){}render();}});
  document.querySelectorAll('[data-major]').forEach(b=>b.onclick=()=>{S.major=+b.dataset.major;render();});
  document.querySelectorAll('[data-spec]').forEach(b=>b.onclick=()=>{S.spec=+b.dataset.spec;render();});
  document.querySelectorAll('[data-simple]').forEach(b=>b.onclick=()=>{S.simple=b.dataset.simple==='1';render();});
  document.querySelectorAll('[data-diff]').forEach(b=>b.onclick=()=>{S.diff=b.dataset.diff;render();});
  document.querySelectorAll('[data-skiprk]').forEach(b=>b.onclick=()=>skipRookie());
  document.querySelectorAll('[data-dropit]').forEach(b=>b.onclick=()=>{const it=S.items.find(x=>x.id===b.dataset.dropit);if(!it)return;S.items=S.items.filter(x=>x!==it);if(it.from){const g=(S.cols||[]).find(c=>c.name===it.from);if(g)g.rel=clamp(g.rel-2,-50,100);}gain('kno',.1);toast(`「${it.title}」을(를) 접었다 · 새 아이템이 더 잘 들어온다`);render();saveGame();});
  document.querySelectorAll('[data-nf]').forEach(b=>b.onclick=()=>{S.netF=b.dataset.nf;render();});document.querySelectorAll('[data-tns]').forEach(b=>b.onclick=()=>{S.netSort=b.dataset.tns;render();});document.querySelectorAll('[data-tss]').forEach(b=>b.onclick=()=>{S.srcSort=b.dataset.tss;render();});document.querySelectorAll('[data-cf]').forEach(b=>b.onclick=()=>{S.colF=b.dataset.cf;render();});document.querySelectorAll('[data-lf]').forEach(b=>b.onclick=()=>{S.logF=b.dataset.lf;render();});
  document.querySelectorAll('[data-smode]').forEach(b=>b.onclick=()=>{S.smode=b.dataset.smode;render();});
  document.querySelectorAll('[data-age]').forEach(b=>b.onclick=()=>{S.age0=+b.dataset.age;render();});
  document.querySelectorAll('[data-apply]').forEach(b=>b.onclick=()=>{const id=b.dataset.apply;if(S.apply.includes(id))S.apply=S.apply.filter(x=>x!==id);else if(S.apply.length<4)S.apply.push(id);else toast('최대 4곳까지 지원할 수 있다');render();});
  document.querySelectorAll('[data-af]').forEach(b=>b.onclick=()=>{S.af=b.dataset.af;render();});{const ap=document.getElementById('advPush');if(ap)ap.onclick=()=>deptAdOpen();const np=document.getElementById('nrPush');if(np)np.onclick=()=>nrPushOpen();const frb=document.getElementById('frontBtn');if(frb)frb.onclick=()=>frontOpen();const fb=document.getElementById('fAdBtn');if(fb)fb.onclick=()=>fAdOpen();}
  document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>{doAction(b.dataset.act);if($('#modal').hidden){try{if(snapFinish())return;}catch(e){}render();saveGame();}});
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{S.tab=b.dataset.tab;render();});
  document.querySelectorAll('[data-tg]').forEach(b=>b.onclick=()=>{const g=(window.__TG||[]).find(x=>x[0]===b.dataset.tg);if(!g)return;const last=S.tabLast&&S.tabLast[g[0]];S.tab=g[2].some(t=>t[0]===last)?last:g[2][0][0];render();});
  document.querySelectorAll('[data-ac]').forEach(b=>b.onclick=()=>{S.actCat=b.dataset.ac;render();});
  const tn=$('#tnm');if(tn){tn.oninput=()=>{S.name=tn.value.trim();$('#tbl').innerHTML=nameLine(tn.value);$('#ncard').classList.toggle('bad',!!(tn.value.trim()&&nameErr(tn.value.trim())));};tn.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const b=document.querySelector('[data-go="new"]');b&&b.click();}};}
  document.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>statInfo(b.dataset.stat));document.querySelectorAll('[data-ev]').forEach(b=>b.onclick=()=>evInfo(b.dataset.ev));
  document.querySelectorAll('[data-dev]').forEach(b=>b.onclick=()=>{const k=b.dataset.dev;if(k==='toggle'){S.devOpen=!S.devOpen;render();return;}devDo(k);});
}